def fetch_all(urls, pages):
    result = {'ok': [], 'missing': []}
    for url in urls:
        if url in pages:
            result['ok'].append(url)
        else:
            result['missing'].append(url)
    return result

def polite_schedule(urls, delay):
    seen = set()
    plan = []
    for url in urls:
        if url in seen:
            continue
        plan.append((url, len(plan) * delay))
        seen.add(url)
    return plan

