from html.parser import HTMLParser

class HeadingParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.headings = []
        self.current = None

    def handle_starttag(self, tag, attrs):
        if tag in ('h1', 'h2', 'h3'):
            self.current = tag

    def handle_endtag(self, tag):
        self.current = None

    def handle_data(self, data):
        if self.current is not None:
            self.headings.append((self.current, data))

from html.parser import HTMLParser

class PriceParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.prices = []
        self.inside = False

    def handle_starttag(self, tag, attrs):
        self.inside = tag == 'span' and ('class', 'price') in attrs

    def handle_endtag(self, tag):
        self.inside = False

    def handle_data(self, data):
        if self.inside:
            text = data.strip().replace('TL', '').strip()
            self.prices.append(float(text.replace('.', '').replace(',', '.')))

